import { describe, it, mock, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import { ExpertError } from "@libretexts/cxone-expert-node";
import { CXOneGate, CXOneUnavailableError, isUpstreamBlock } from "./gate.js";

const CLOUDFRONT_403 =
  "<HTML><BODY><H1>403 ERROR</H1>Request blocked.<PRE>Generated by cloudfront (CloudFront)</PRE></BODY></HTML>";

const httpError = (status: number, responseData: unknown) =>
  new ExpertError(`status ${status}`, { kind: "http", status, responseData });

const newGate = () =>
  new CXOneGate({
    maxInFlight: 2,
    minIntervalMs: 0,
    baseCooldownMs: 60_000,
    maxCooldownMs: 240_000,
  });

describe("isUpstreamBlock", () => {
  it("trips on 429 and on CloudFront's 403 page only", () => {
    assert.equal(isUpstreamBlock(429, undefined), true);
    assert.equal(isUpstreamBlock(403, CLOUDFRONT_403), true);
    assert.equal(isUpstreamBlock(403, { error: "forbidden" }), false);
    assert.equal(isUpstreamBlock(403, "<error><status>403</status></error>"), false);
    assert.equal(isUpstreamBlock(404, CLOUDFRONT_403), false);
  });
});

describe("CXOneGate breaker", () => {
  // Cast: the installed @types/node predates the object form Node 22 accepts.
  beforeEach(() => mock.timers.enable({ apis: ["Date"], now: 0 } as never));
  afterEach(() => mock.timers.reset());

  it("opens on a CloudFront 403 and skips the network while open", async () => {
    const gate = newGate();
    await assert.rejects(
      gate.run(() => Promise.reject(httpError(403, CLOUDFRONT_403))),
      ExpertError,
    );

    const fn = mock.fn(async () => "ok");
    await assert.rejects(gate.run(fn), CXOneUnavailableError);
    assert.equal(fn.mock.callCount(), 0);
  });

  it("ignores MindTouch 403s and 404s", async () => {
    const gate = newGate();
    await assert.rejects(gate.run(() => Promise.reject(httpError(403, { msg: "denied" }))));
    await assert.rejects(gate.run(() => Promise.reject(httpError(404, "not found"))));
    assert.equal(await gate.run(async () => "ok"), "ok");
  });

  it("closes after a successful probe", async () => {
    const gate = newGate();
    await assert.rejects(gate.run(() => Promise.reject(httpError(429, ""))));
    mock.timers.tick(60_000);
    assert.equal(await gate.run(async () => "probe"), "probe");
    assert.equal(await gate.run(async () => "after"), "after");
  });

  it("doubles the cool-down when the probe is blocked", async () => {
    const gate = newGate();
    await assert.rejects(gate.run(() => Promise.reject(httpError(429, ""))));
    mock.timers.tick(60_000);
    await assert.rejects(gate.run(() => Promise.reject(httpError(429, ""))), ExpertError);

    mock.timers.tick(60_000);
    await assert.rejects(gate.run(async () => "x"), CXOneUnavailableError);
    mock.timers.tick(60_000);
    assert.equal(await gate.run(async () => "probe"), "probe");
  });

  it("detects blocks on fetch responses", async () => {
    const gate = newGate();
    const fetchMock = mock.method(globalThis, "fetch", async () =>
      new Response(CLOUDFRONT_403, { status: 403 }),
    );
    const res = await gate.fetch("https://chem.libretexts.org/@api/deki/pages/1");
    assert.equal(res.status, 403);
    await assert.rejects(gate.fetch("https://chem.libretexts.org/x"), CXOneUnavailableError);
    assert.equal(fetchMock.mock.callCount(), 1);
    fetchMock.mock.restore();
  });
});

describe("CXOneGate concurrency", () => {
  it("never runs more than maxInFlight at once", async () => {
    const gate = newGate();
    let active = 0;
    let peak = 0;
    const task = () =>
      gate.run(async () => {
        active++;
        peak = Math.max(peak, active);
        await new Promise((r) => setImmediate(r));
        active--;
      });
    await Promise.all(Array.from({ length: 8 }, task));
    assert.equal(peak, 2);
  });

  it("rejects queued callers when the breaker opens, without waiting for a paced slot", async () => {
    mock.timers.enable({ apis: ["Date", "setTimeout"], now: 0 } as never);
    try {
      const gate = new CXOneGate({
        maxInFlight: 1,
        minIntervalMs: 1000,
        baseCooldownMs: 60_000,
        maxCooldownMs: 240_000,
      });
      let block!: (e: unknown) => void;
      const first = gate.run(() => new Promise((_, reject) => (block = reject)));
      const fn = mock.fn(async () => "ok");
      const queued = gate.run(fn);
      await new Promise((r) => setImmediate(r));
      block(httpError(429, ""));
      await assert.rejects(first, ExpertError);
      // No timer tick: a call that booked a 1000ms pace slot would still be pending here.
      await assert.rejects(queued, CXOneUnavailableError);
      assert.equal(fn.mock.callCount(), 0);
    } finally {
      mock.timers.reset();
    }
  });
});

describe("CXOneGate.waitUntilClosed", () => {
  beforeEach(() => mock.timers.enable({ apis: ["Date", "setTimeout"], now: 0 } as never));
  afterEach(() => mock.timers.reset());

  it("resolves at once while closed", async () => {
    await newGate().waitUntilClosed(0);
  });

  it("waits out the cool-down, or throws if that passes the deadline", async () => {
    const gate = newGate();
    await assert.rejects(gate.run(() => Promise.reject(httpError(429, ""))));
    assert.equal(gate.retryAfterMs, 60_000);
    await assert.rejects(gate.waitUntilClosed(59_999), CXOneUnavailableError);

    let done = false;
    const wait = gate.waitUntilClosed(60_000).then(() => (done = true));
    mock.timers.tick(59_999);
    await Promise.resolve();
    assert.equal(done, false);
    mock.timers.tick(1);
    await wait;
    assert.equal(gate.retryAfterMs, 0);
  });
});
